public int MaxConsecutiveOnesScan(int n)
{
    int maxCount = 0;
    int current = 0;
    while (n > 0)
    {
        if ((n & 1) == 1)
            current++;
        else
            current = 0;
        maxCount = Math.Max(maxCount, current);
        n >>= 1;
    }
    return maxCount;
}

public int MaxConsecutiveOnesKernighan(int n)
{
    int maxCount = 0;
    int current = 0;
    while (n > 0)
    {
        if ((n & 1) == 1)
            current++;
        else
            current = 0;
        maxCount = Math.Max(maxCount, current);
        n &= n - 1;
    }
    return maxCount;
}
